-- 12_reconcile.sql  (Snowflake, v2)
-- Weakness #6: MEMBER_INDEX is a derived structure and must never silently disagree with the
-- country tables or the history. Every statement below returns ONE ROW PER VIOLATION
-- (first column = check name). The runner executes them after each load and fails the load
-- if any returns a row; the Python equivalent is CountryStore.reconcile().
-- Requires MEMBER_ALL (generated by the runner), which carries table_name per branch.
USE SCHEMA SKYPOINTS.CORE;

-- 1. index entry with no row in the country it points to
SELECT 'index_without_row' AS check_name, i.member_key, i.country_code AS detail
  FROM MEMBER_INDEX i
  LEFT JOIN MEMBER_ALL m ON m.member_key = i.member_key AND m.country_code = i.country_code
 WHERE m.member_key IS NULL;

-- 2. country-table row with no index entry
SELECT 'row_without_index' AS check_name, m.member_key, m.table_name AS detail
  FROM MEMBER_ALL m
  LEFT JOIN MEMBER_INDEX i ON i.member_key = m.member_key
 WHERE i.member_key IS NULL;

-- 3. member present in more than one country table
SELECT 'duplicate_across_tables' AS check_name, member_key, LISTAGG(table_name, ',') AS detail
  FROM MEMBER_ALL
 GROUP BY member_key
HAVING COUNT(*) > 1;

-- 4. row stored in the wrong country table (country_code disagrees with its table)
SELECT 'wrong_table' AS check_name, m.member_key, m.table_name || ' vs ' || m.country_code AS detail
  FROM MEMBER_ALL m
  JOIN DIM_COUNTRY d ON d.country_code = m.country_code
 WHERE m.table_name <> d.target_table;

-- 5. index and row disagree about the country
SELECT 'index_country_mismatch' AS check_name, m.member_key, i.country_code || ' vs ' || m.country_code AS detail
  FROM MEMBER_ALL m
  JOIN MEMBER_INDEX i ON i.member_key = m.member_key
 WHERE i.country_code <> m.country_code;

-- 6. history: every indexed member needs exactly one current row, in the indexed country
SELECT 'history_no_current' AS check_name, i.member_key, NULL AS detail
  FROM MEMBER_INDEX i
  LEFT JOIN MEMBER_HISTORY h ON h.member_key = i.member_key AND h.is_current
 WHERE h.member_key IS NULL;

SELECT 'history_multiple_current' AS check_name, member_key, COUNT(*)::VARCHAR AS detail
  FROM MEMBER_HISTORY
 WHERE is_current
 GROUP BY member_key
HAVING COUNT(*) > 1;

SELECT 'history_country_mismatch' AS check_name, i.member_key, h.country_code || ' vs ' || i.country_code AS detail
  FROM MEMBER_INDEX i
  JOIN MEMBER_HISTORY h ON h.member_key = i.member_key AND h.is_current
 WHERE h.country_code <> i.country_code;
